CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Login identity and the address invitations are sent to.
	"email" VARCHAR(320) NOT NULL UNIQUE,
	-- Display name shown on mentions, comments and edit attribution.
	"full_name" VARCHAR(160) NOT NULL,
	-- Profile image URL.
	"avatar_url" VARCHAR(500),
	-- Account creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A person, global across workspaces. One account can belong to a personal workspace and three employers, which is why membership is a separate table rather than a column here.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."email" IS 'Login identity and the address invitations are sent to.';
COMMENT ON COLUMN "users"."full_name" IS 'Display name shown on mentions, comments and edit attribution.';
COMMENT ON COLUMN "users"."avatar_url" IS 'Profile image URL.';
COMMENT ON COLUMN "users"."created_at" IS 'Account creation time.';

CREATE TABLE IF NOT EXISTS "workspaces" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Workspace name shown in the sidebar switcher.
	"name" VARCHAR(160) NOT NULL,
	-- Email domain for automatic join. Null for workspaces that only accept explicit invitations.
	"domain" VARCHAR(120) UNIQUE,
	-- viewer | commenter | editor. The permission every member gets on a top-level page unless an explicit grant narrows it.
	"default_page_role" VARCHAR(16) NOT NULL DEFAULT 'editor',
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "workspaces" IS 'The tenancy boundary. Every page, database and permission is scoped here, so a workspace is the unit that can be exported, billed or deleted whole.';
COMMENT ON COLUMN "workspaces"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "workspaces"."name" IS 'Workspace name shown in the sidebar switcher.';
COMMENT ON COLUMN "workspaces"."domain" IS 'Email domain for automatic join. Null for workspaces that only accept explicit invitations.';
COMMENT ON COLUMN "workspaces"."default_page_role" IS 'viewer | commenter | editor. The permission every member gets on a top-level page unless an explicit grant narrows it.';
COMMENT ON COLUMN "workspaces"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "workspace_members" (
	-- Workspace joined. Half of the composite primary key.
	"workspace_id" BIGINT,
	-- Member. The other half of the key.
	"user_id" BIGINT,
	-- owner | admin | member | guest. A guest sees only pages explicitly shared with them and never the workspace tree, which is why it is a role rather than an absence of one.
	"role" VARCHAR(16) NOT NULL DEFAULT 'member',
	-- When the member joined.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("workspace_id", "user_id")
);

COMMENT ON TABLE "workspace_members" IS 'Membership and workspace-wide role. The composite key prevents duplicate membership and the reverse index renders the workspace switcher.';
COMMENT ON COLUMN "workspace_members"."workspace_id" IS 'Workspace joined. Half of the composite primary key.';
COMMENT ON COLUMN "workspace_members"."user_id" IS 'Member. The other half of the key.';
COMMENT ON COLUMN "workspace_members"."role" IS 'owner | admin | member | guest. A guest sees only pages explicitly shared with them and never the workspace tree, which is why it is a role rather than an absence of one.';
COMMENT ON COLUMN "workspace_members"."joined_at" IS 'When the member joined.';

CREATE INDEX "idx_workspace_members_user"
ON "workspace_members" ("user_id");

CREATE TABLE IF NOT EXISTS "pages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning workspace, denormalised onto every page so tenancy filtering never walks the parent chain.
	"workspace_id" BIGINT NOT NULL,
	-- Parent in the sidebar tree. Null for a top-level page, which is also where permission inheritance stops.
	"parent_page_id" BIGINT,
	-- Set when this page is a row of a database. A database row is a page in every respect, which is what lets any row open as a full document with its own sub-pages.
	"database_id" BIGINT,
	-- Page title. Stored here rather than as the first block so the sidebar, search and backlinks render without loading the document.
	"title" VARCHAR(1000) NOT NULL DEFAULT 'Untitled',
	-- Emoji or image URL shown in the sidebar and on cards.
	"icon" VARCHAR(255),
	-- Header image.
	"cover_url" VARCHAR(1000),
	-- Sort key among siblings in the sidebar. A fractional position means a drag rewrites one row, the same trick the board ordering in the project management example uses.
	"position" NUMERIC(30,15) NOT NULL,
	-- Template pages are excluded from search and from database row counts, and are duplicated rather than opened.
	"is_template" BOOLEAN NOT NULL DEFAULT false,
	-- Author. Null if the account was hard deleted.
	"created_by_id" BIGINT,
	-- Most recent editor, shown in the page footer.
	"last_edited_by_id" BIGINT,
	-- Soft delete into the trash. Archiving a page hides its whole subtree without touching the descendant rows, so a restore is one update.
	"archived_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last edit to the page or any of its blocks, which is what the recently-visited list sorts on.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "pages" IS 'A page: a document, a sub-page, or a row of a database. Collapsing all three into one entity is why permissions, comments, search and the block tree need exactly one implementation instead of three.';
COMMENT ON COLUMN "pages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "pages"."workspace_id" IS 'Owning workspace, denormalised onto every page so tenancy filtering never walks the parent chain.';
COMMENT ON COLUMN "pages"."parent_page_id" IS 'Parent in the sidebar tree. Null for a top-level page, which is also where permission inheritance stops.';
COMMENT ON COLUMN "pages"."database_id" IS 'Set when this page is a row of a database. A database row is a page in every respect, which is what lets any row open as a full document with its own sub-pages.';
COMMENT ON COLUMN "pages"."title" IS 'Page title. Stored here rather than as the first block so the sidebar, search and backlinks render without loading the document.';
COMMENT ON COLUMN "pages"."icon" IS 'Emoji or image URL shown in the sidebar and on cards.';
COMMENT ON COLUMN "pages"."cover_url" IS 'Header image.';
COMMENT ON COLUMN "pages"."position" IS 'Sort key among siblings in the sidebar. A fractional position means a drag rewrites one row, the same trick the board ordering in the project management example uses.';
COMMENT ON COLUMN "pages"."is_template" IS 'Template pages are excluded from search and from database row counts, and are duplicated rather than opened.';
COMMENT ON COLUMN "pages"."created_by_id" IS 'Author. Null if the account was hard deleted.';
COMMENT ON COLUMN "pages"."last_edited_by_id" IS 'Most recent editor, shown in the page footer.';
COMMENT ON COLUMN "pages"."archived_at" IS 'Soft delete into the trash. Archiving a page hides its whole subtree without touching the descendant rows, so a restore is one update.';
COMMENT ON COLUMN "pages"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "pages"."updated_at" IS 'Last edit to the page or any of its blocks, which is what the recently-visited list sorts on.';

CREATE INDEX "idx_pages_sidebar"
ON "pages" ("workspace_id", "parent_page_id", "position");
CREATE INDEX "idx_pages_database_rows"
ON "pages" ("database_id", "updated_at");

CREATE TABLE IF NOT EXISTS "blocks" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Page the block belongs to, denormalised through the whole tree. Loading a document is then one indexed read of every block on the page rather than a recursive descent.
	"page_id" BIGINT NOT NULL,
	-- Parent block. Null for a top-level block on the page. This self-reference is what makes a toggle contain a list which contains a paragraph.
	"parent_block_id" BIGINT,
	-- paragraph | heading_1 | bulleted_list_item | to_do | toggle | code | image | divider | child_page | child_database | column_list. The type decides how content is interpreted and nothing else.
	"block_type" VARCHAR(40) NOT NULL,
	-- Type-specific payload: rich text runs with their marks and mentions, a code language, an image key. JSON because a new block type must not require a migration, and because rich text is a nested structure no column layout expresses honestly.
	"content" JSONB NOT NULL,
	-- Sort key among siblings under the same parent. Inserting between two blocks averages their positions, so pressing Enter mid-document writes one row instead of renumbering everything below it.
	"position" NUMERIC(30,15) NOT NULL,
	-- Target page for a child_page or child_database block. It is the link between the block tree and the page tree, which is how a sub-page appears both inline in the document and in the sidebar.
	"child_page_id" BIGINT,
	-- Who inserted the block.
	"created_by_id" BIGINT,
	-- Who last changed it, used for per-block edit attribution.
	"last_edited_by_id" BIGINT,
	-- Soft delete, so an undo after a stray backspace restores the subtree with its children intact.
	"archived_at" TIMESTAMPTZ,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Last edit.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "blocks" IS 'The centrepiece: a document is not a text field, it is an ordered tree of these. Every paragraph, heading and checkbox is a row that can be linked to, commented on, moved and permissioned independently.';
COMMENT ON COLUMN "blocks"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "blocks"."page_id" IS 'Page the block belongs to, denormalised through the whole tree. Loading a document is then one indexed read of every block on the page rather than a recursive descent.';
COMMENT ON COLUMN "blocks"."parent_block_id" IS 'Parent block. Null for a top-level block on the page. This self-reference is what makes a toggle contain a list which contains a paragraph.';
COMMENT ON COLUMN "blocks"."block_type" IS 'paragraph | heading_1 | bulleted_list_item | to_do | toggle | code | image | divider | child_page | child_database | column_list. The type decides how content is interpreted and nothing else.';
COMMENT ON COLUMN "blocks"."content" IS 'Type-specific payload: rich text runs with their marks and mentions, a code language, an image key. JSON because a new block type must not require a migration, and because rich text is a nested structure no column layout expresses honestly.';
COMMENT ON COLUMN "blocks"."position" IS 'Sort key among siblings under the same parent. Inserting between two blocks averages their positions, so pressing Enter mid-document writes one row instead of renumbering everything below it.';
COMMENT ON COLUMN "blocks"."child_page_id" IS 'Target page for a child_page or child_database block. It is the link between the block tree and the page tree, which is how a sub-page appears both inline in the document and in the sidebar.';
COMMENT ON COLUMN "blocks"."created_by_id" IS 'Who inserted the block.';
COMMENT ON COLUMN "blocks"."last_edited_by_id" IS 'Who last changed it, used for per-block edit attribution.';
COMMENT ON COLUMN "blocks"."archived_at" IS 'Soft delete, so an undo after a stray backspace restores the subtree with its children intact.';
COMMENT ON COLUMN "blocks"."created_at" IS 'Creation time.';
COMMENT ON COLUMN "blocks"."updated_at" IS 'Last edit.';

CREATE INDEX "idx_blocks_tree_order"
ON "blocks" ("page_id", "parent_block_id", "position");
CREATE INDEX "idx_blocks_child_page"
ON "blocks" ("child_page_id");

CREATE TABLE IF NOT EXISTS "databases" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- The page that is this database. Unique because a database lives on exactly one page, which is what gives it a place in the sidebar, an icon and a permission row for free.
	"page_id" BIGINT NOT NULL UNIQUE,
	-- Which property renders as the row title. Null only during creation, before the first property exists.
	"title_property_id" BIGINT,
	-- Explanation shown above the view, usually conventions for filling rows in.
	"description" TEXT,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "databases" IS 'A user-defined table. It has no columns of its own in this schema: the shape is data in database_properties, because users add properties at runtime and a real column per property would mean a DDL statement per click.';
COMMENT ON COLUMN "databases"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "databases"."page_id" IS 'The page that is this database. Unique because a database lives on exactly one page, which is what gives it a place in the sidebar, an icon and a permission row for free.';
COMMENT ON COLUMN "databases"."title_property_id" IS 'Which property renders as the row title. Null only during creation, before the first property exists.';
COMMENT ON COLUMN "databases"."description" IS 'Explanation shown above the view, usually conventions for filling rows in.';
COMMENT ON COLUMN "databases"."created_at" IS 'Creation time.';

CREATE TABLE IF NOT EXISTS "database_properties" (
	-- Surrogate primary key referenced by values, filters and sorts.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning database.
	"database_id" BIGINT NOT NULL,
	-- Column header. Renamed freely because values reference the id, so a rename never rewrites a row.
	"name" VARCHAR(200) NOT NULL,
	-- text | number | select | multi_select | date | person | checkbox | url | relation | formula | rollup. Type changes are allowed and coerce existing values, which is why values are stored as JSON rather than in typed columns.
	"property_type" VARCHAR(32) NOT NULL DEFAULT 'text',
	-- Type-specific settings: the option list and colours for a select, the number format, the target database for a relation, the expression for a formula.
	"config" JSONB,
	-- Left-to-right order in the default table view. Per-view column order and visibility are a view concern, not a schema concern.
	"position" NUMERIC(30,15) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "database_properties" IS 'One user-defined column. Storing the schema as rows is what lets someone add a property to a ten-thousand-row database instantly, with no migration and no lock.';
COMMENT ON COLUMN "database_properties"."id" IS 'Surrogate primary key referenced by values, filters and sorts.';
COMMENT ON COLUMN "database_properties"."database_id" IS 'Owning database.';
COMMENT ON COLUMN "database_properties"."name" IS 'Column header. Renamed freely because values reference the id, so a rename never rewrites a row.';
COMMENT ON COLUMN "database_properties"."property_type" IS 'text | number | select | multi_select | date | person | checkbox | url | relation | formula | rollup. Type changes are allowed and coerce existing values, which is why values are stored as JSON rather than in typed columns.';
COMMENT ON COLUMN "database_properties"."config" IS 'Type-specific settings: the option list and colours for a select, the number format, the target database for a relation, the expression for a formula.';
COMMENT ON COLUMN "database_properties"."position" IS 'Left-to-right order in the default table view. Per-view column order and visibility are a view concern, not a schema concern.';
COMMENT ON COLUMN "database_properties"."created_at" IS 'Creation time.';

CREATE INDEX "idx_database_properties_order"
ON "database_properties" ("database_id", "position");

CREATE TABLE IF NOT EXISTS "page_property_values" (
	-- The database row, which is a page. Half of the composite primary key.
	"page_id" BIGINT,
	-- Property being set. The other half of the key, so one row holds one value per property.
	"property_id" BIGINT,
	-- The value, shaped by the property type: a string, a number, an array of option ids, an ISO date range, an array of user ids. Null and an absent row both mean empty, so clearing a cell can delete the row.
	"value" JSONB,
	-- Last change to this cell, which is what a per-cell edit history and conflict resolution need.
	"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("page_id", "property_id")
);

COMMENT ON TABLE "page_property_values" IS 'The sparse cell store. Rows only exist for cells that have been filled, so a database with forty properties where most rows use six costs six rows, not forty.';
COMMENT ON COLUMN "page_property_values"."page_id" IS 'The database row, which is a page. Half of the composite primary key.';
COMMENT ON COLUMN "page_property_values"."property_id" IS 'Property being set. The other half of the key, so one row holds one value per property.';
COMMENT ON COLUMN "page_property_values"."value" IS 'The value, shaped by the property type: a string, a number, an array of option ids, an ISO date range, an array of user ids. Null and an absent row both mean empty, so clearing a cell can delete the row.';
COMMENT ON COLUMN "page_property_values"."updated_at" IS 'Last change to this cell, which is what a per-cell edit history and conflict resolution need.';

CREATE INDEX "idx_page_property_values_property"
ON "page_property_values" ("property_id");

CREATE TABLE IF NOT EXISTS "database_views" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Database being viewed.
	"database_id" BIGINT NOT NULL,
	-- Tab label such as By owner or This week.
	"name" VARCHAR(200) NOT NULL,
	-- table | board | calendar | gallery | list | timeline. The same rows rendered differently; no view owns any data.
	"view_kind" VARCHAR(24) NOT NULL DEFAULT 'table',
	-- Property whose values become board columns or calendar lanes. Null for table and list views.
	"group_by_property_id" BIGINT,
	-- Property placed on the calendar or timeline axis. Null for the other kinds.
	"date_property_id" BIGINT,
	-- Ordered array of property ids shown in this view. An array rather than a join table because it is read and written whole, always, and never queried across views.
	"visible_property_ids" JSONB,
	-- Order of the view tabs.
	"position" NUMERIC(30,15) NOT NULL,
	-- Creation time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "database_views" IS 'A saved way of looking at one database. Views are the reason the same set of rows can be a kanban board for one person and a calendar for another, with no duplication of data.';
COMMENT ON COLUMN "database_views"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "database_views"."database_id" IS 'Database being viewed.';
COMMENT ON COLUMN "database_views"."name" IS 'Tab label such as By owner or This week.';
COMMENT ON COLUMN "database_views"."view_kind" IS 'table | board | calendar | gallery | list | timeline. The same rows rendered differently; no view owns any data.';
COMMENT ON COLUMN "database_views"."group_by_property_id" IS 'Property whose values become board columns or calendar lanes. Null for table and list views.';
COMMENT ON COLUMN "database_views"."date_property_id" IS 'Property placed on the calendar or timeline axis. Null for the other kinds.';
COMMENT ON COLUMN "database_views"."visible_property_ids" IS 'Ordered array of property ids shown in this view. An array rather than a join table because it is read and written whole, always, and never queried across views.';
COMMENT ON COLUMN "database_views"."position" IS 'Order of the view tabs.';
COMMENT ON COLUMN "database_views"."created_at" IS 'Creation time.';

CREATE INDEX "idx_database_views_order"
ON "database_views" ("database_id", "position");

CREATE TABLE IF NOT EXISTS "view_filters" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Owning view.
	"view_id" BIGINT NOT NULL,
	-- Property being tested.
	"property_id" BIGINT NOT NULL,
	-- Parent group, which is how nested and-or logic is expressed. Null for a top-level condition.
	"parent_filter_id" BIGINT,
	-- and | or. It applies between this condition and its siblings, so a group carries one combinator rather than one per pair.
	"conjunction" VARCHAR(3) NOT NULL DEFAULT 'and',
	-- equals | not_equals | contains | is_empty | before | after | on_or_after | is_any_of. Constrained by the property type in the UI, stored as a plain string so a new operator is not a migration.
	"operator" VARCHAR(32) NOT NULL,
	-- Comparison value, shaped like the property value it is tested against. Null for the unary operators such as is_empty.
	"operand" JSONB,
	-- Display order within the group.
	"ordinal" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "view_filters" IS 'One condition in a view filter, stored as rows so the tree can be nested. Keeping it structured rather than as one JSON blob means the query planner can be handed real predicates instead of a parsed string.';
COMMENT ON COLUMN "view_filters"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "view_filters"."view_id" IS 'Owning view.';
COMMENT ON COLUMN "view_filters"."property_id" IS 'Property being tested.';
COMMENT ON COLUMN "view_filters"."parent_filter_id" IS 'Parent group, which is how nested and-or logic is expressed. Null for a top-level condition.';
COMMENT ON COLUMN "view_filters"."conjunction" IS 'and | or. It applies between this condition and its siblings, so a group carries one combinator rather than one per pair.';
COMMENT ON COLUMN "view_filters"."operator" IS 'equals | not_equals | contains | is_empty | before | after | on_or_after | is_any_of. Constrained by the property type in the UI, stored as a plain string so a new operator is not a migration.';
COMMENT ON COLUMN "view_filters"."operand" IS 'Comparison value, shaped like the property value it is tested against. Null for the unary operators such as is_empty.';
COMMENT ON COLUMN "view_filters"."ordinal" IS 'Display order within the group.';

CREATE INDEX "idx_view_filters_view"
ON "view_filters" ("view_id");

CREATE TABLE IF NOT EXISTS "view_sorts" (
	-- Owning view. Half of the composite primary key.
	"view_id" BIGINT,
	-- Property sorted on. The other half of the key, which also stops the same property being added to the sort twice.
	"property_id" BIGINT,
	-- asc | desc.
	"direction" VARCHAR(4) NOT NULL DEFAULT 'asc',
	-- Sort precedence, lowest first. Multi-level sorting is the common case, so precedence is explicit rather than implied by insertion order.
	"ordinal" SMALLINT NOT NULL DEFAULT 0,
	PRIMARY KEY("view_id", "property_id")
);

COMMENT ON TABLE "view_sorts" IS 'The ordering rules of a view. Separate from filters because sorting never changes which rows appear, only their sequence, and the two are edited independently.';
COMMENT ON COLUMN "view_sorts"."view_id" IS 'Owning view. Half of the composite primary key.';
COMMENT ON COLUMN "view_sorts"."property_id" IS 'Property sorted on. The other half of the key, which also stops the same property being added to the sort twice.';
COMMENT ON COLUMN "view_sorts"."direction" IS 'asc | desc.';
COMMENT ON COLUMN "view_sorts"."ordinal" IS 'Sort precedence, lowest first. Multi-level sorting is the common case, so precedence is explicit rather than implied by insertion order.';

CREATE TABLE IF NOT EXISTS "page_permissions" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Page the grant is attached to. Only pages that override their parent have rows here.
	"page_id" BIGINT NOT NULL,
	-- Grantee. Null when the grant applies to everyone in the workspace.
	"user_id" BIGINT,
	-- True for a grant to every member. Keeping it explicit avoids a synthetic everyone user and keeps user_id a real foreign key.
	"is_workspace_wide" BOOLEAN NOT NULL DEFAULT false,
	-- viewer | commenter | editor | full_access. Full access adds the right to change permissions, which is why it is not simply the highest edit level.
	"role" VARCHAR(16) NOT NULL,
	-- Token for an unauthenticated share link. Set on the row that represents public access; null on every normal grant, and the unique index makes a token collision impossible.
	"public_link_token" CHAR(32) UNIQUE,
	-- Who shared it, shown in the share dialog.
	"granted_by_id" BIGINT,
	-- When access was granted.
	"granted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "page_permissions" IS 'An explicit grant that overrides inheritance. Effective access is resolved by walking parent_page_id upward until a page has rows here, so the common case of a whole subtree sharing one setting costs a single row.';
COMMENT ON COLUMN "page_permissions"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "page_permissions"."page_id" IS 'Page the grant is attached to. Only pages that override their parent have rows here.';
COMMENT ON COLUMN "page_permissions"."user_id" IS 'Grantee. Null when the grant applies to everyone in the workspace.';
COMMENT ON COLUMN "page_permissions"."is_workspace_wide" IS 'True for a grant to every member. Keeping it explicit avoids a synthetic everyone user and keeps user_id a real foreign key.';
COMMENT ON COLUMN "page_permissions"."role" IS 'viewer | commenter | editor | full_access. Full access adds the right to change permissions, which is why it is not simply the highest edit level.';
COMMENT ON COLUMN "page_permissions"."public_link_token" IS 'Token for an unauthenticated share link. Set on the row that represents public access; null on every normal grant, and the unique index makes a token collision impossible.';
COMMENT ON COLUMN "page_permissions"."granted_by_id" IS 'Who shared it, shown in the share dialog.';
COMMENT ON COLUMN "page_permissions"."granted_at" IS 'When access was granted.';

CREATE UNIQUE INDEX "uq_page_permissions_page_user"
ON "page_permissions" ("page_id", "user_id");
CREATE INDEX "idx_page_permissions_user"
ON "page_permissions" ("user_id");

CREATE TABLE IF NOT EXISTS "comments" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Page the discussion lives on, stored even for block comments so the inbox and page-level queries do not join through blocks.
	"page_id" BIGINT NOT NULL,
	-- Block the comment is anchored to. Null for a page-level comment at the top of the document.
	"block_id" BIGINT,
	-- First comment of the thread. Null on the opener, which is what makes a thread a two-level structure rather than an arbitrary tree.
	"parent_comment_id" BIGINT,
	-- Who wrote it. Null if the account was hard deleted.
	"author_id" BIGINT,
	-- Rich text runs, the same shape as block content, so mentions and links behave identically in a comment and in the document.
	"body" JSONB NOT NULL,
	-- Copy of the text the comment was attached to. Kept because the block can be edited out from under the comment, and an orphaned thread with no quoted context is unreadable.
	"anchor_text" VARCHAR(500),
	-- When the thread was resolved. Resolved threads are hidden rather than deleted, because the decision recorded in them is often the reason the paragraph reads the way it does.
	"resolved_at" TIMESTAMPTZ,
	-- Who resolved it.
	"resolved_by_id" BIGINT,
	-- Submission time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "comments" IS 'Discussion anchored to a block. Anchoring to a block rather than a character range is what keeps a comment attached through an edit, and the snapshotted anchor text is the fallback for when the block is rewritten entirely.';
COMMENT ON COLUMN "comments"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "comments"."page_id" IS 'Page the discussion lives on, stored even for block comments so the inbox and page-level queries do not join through blocks.';
COMMENT ON COLUMN "comments"."block_id" IS 'Block the comment is anchored to. Null for a page-level comment at the top of the document.';
COMMENT ON COLUMN "comments"."parent_comment_id" IS 'First comment of the thread. Null on the opener, which is what makes a thread a two-level structure rather than an arbitrary tree.';
COMMENT ON COLUMN "comments"."author_id" IS 'Who wrote it. Null if the account was hard deleted.';
COMMENT ON COLUMN "comments"."body" IS 'Rich text runs, the same shape as block content, so mentions and links behave identically in a comment and in the document.';
COMMENT ON COLUMN "comments"."anchor_text" IS 'Copy of the text the comment was attached to. Kept because the block can be edited out from under the comment, and an orphaned thread with no quoted context is unreadable.';
COMMENT ON COLUMN "comments"."resolved_at" IS 'When the thread was resolved. Resolved threads are hidden rather than deleted, because the decision recorded in them is often the reason the paragraph reads the way it does.';
COMMENT ON COLUMN "comments"."resolved_by_id" IS 'Who resolved it.';
COMMENT ON COLUMN "comments"."created_at" IS 'Submission time.';

CREATE INDEX "idx_comments_page_time"
ON "comments" ("page_id", "created_at");
CREATE INDEX "idx_comments_block_open"
ON "comments" ("block_id", "resolved_at");

